/* ============== INTRO: bud -> huge blooming flower -> wrapped bouquet ============== */
(function(){
  const SVGNS = 'http://www.w3.org/2000/svg';
  function el(tag, attrs){
    const e = document.createElementNS(SVGNS, tag);
    for(const k in attrs) e.setAttribute(k, attrs[k]);
    return e;
  }

  const introOverlay = document.getElementById('introOverlay');
  const phaseBud = document.getElementById('phaseBud');
  const phaseBloom = document.getElementById('phaseBloom');
  const phaseBouquet = document.getElementById('phaseBouquet');
  const openBtn = document.getElementById('openBtn');
  const continueBtn = document.getElementById('continueBtn');

  function showPhase(target){
    [phaseBud, phaseBloom, phaseBouquet].forEach(p=>p.classList.remove('active'));
    target.classList.add('active');
  }

  function sparkleBurst(container, count){
    const emojis = ['✨','💫','🌟'];
    for(let i=0;i<count;i++){
      setTimeout(()=>{
        const s = document.createElement('span');
        s.className = 'intro-sparkle';
        s.textContent = emojis[Math.floor(Math.random()*emojis.length)];
        s.style.left = (28 + Math.random()*44) + '%';
        s.style.top = (22 + Math.random()*44) + '%';
        container.appendChild(s);
        setTimeout(()=>s.remove(), 1200);
      }, i*80);
    }
  }

  /* ---------- tiny closed bud icon ---------- */
  function buildBud(){
    const svg = document.getElementById('budSvg');
    svg.innerHTML = '';
    const g = el('g', {transform:'translate(60,66)'});
    const petalAngles = [-26,-13,0,13,26];
    petalAngles.forEach(a=>{
      const p = el('ellipse', {cx:0, cy:-14, rx:11, ry:26, fill:'#9b7ebd', opacity:'0.9', transform:`rotate(${a})`});
      g.appendChild(p);
    });
    const core = el('ellipse', {cx:0, cy:-14, rx:9, ry:22, fill:'#7a5aa6'});
    g.appendChild(core);
    svg.appendChild(g);
    const stem = el('line', {x1:60, y1:80, x2:60, y2:112, stroke:'#6fae5c', 'stroke-width':4, 'stroke-linecap':'round'});
    svg.appendChild(stem);
  }
  buildBud();

  /* ---------- huge blooming flower ---------- */
  function buildBigFlower(){
    const svg = document.getElementById('bigFlowerSvg');
    svg.innerHTML = '';

    const defs = el('defs', {});
    defs.innerHTML = `
      <linearGradient id="petalOuter" x1="0" y1="1" x2="0" y2="0">
        <stop offset="0%" stop-color="#e9defa"/>
        <stop offset="100%" stop-color="#f0a3c2"/>
      </linearGradient>
      <linearGradient id="petalMid" x1="0" y1="1" x2="0" y2="0">
        <stop offset="0%" stop-color="#c58ed6"/>
        <stop offset="100%" stop-color="#9b7ebd"/>
      </linearGradient>
      <linearGradient id="petalInner" x1="0" y1="1" x2="0" y2="0">
        <stop offset="0%" stop-color="#8a5fb0"/>
        <stop offset="100%" stop-color="#5f4587"/>
      </linearGradient>
      <radialGradient id="flowerCenter" cx="35%" cy="35%" r="70%">
        <stop offset="0%" stop-color="#fff6da"/>
        <stop offset="100%" stop-color="#f0c96b"/>
      </radialGradient>
    `;
    svg.appendChild(defs);

    const root = el('g', {id:'flowerSpinWrap'});
    svg.appendChild(root);

    function petalLayer(count, rx, ry, cy, offsetDeg, fill, startDelay, stepDelay){
      const layer = el('g', {});
      for(let i=0;i<count;i++){
        const angle = (360/count)*i + offsetDeg;
        const pg = el('g', {class:'petal-g'});
        pg.style.setProperty('--rot', angle + 'deg');
        pg.style.setProperty('--pd', (startDelay + i*stepDelay) + 's');
        const petal = el('ellipse', {cx:200, cy:cy, rx:rx, ry:ry, fill:fill, opacity:'0.96'});
        pg.appendChild(petal);
        layer.appendChild(pg);
      }
      root.appendChild(layer);
    }

    petalLayer(14, 24, 98, 105, 0,  'url(#petalOuter)', 0,    0.025);
    petalLayer(12, 18, 70, 132, 15, 'url(#petalMid)',   0.32, 0.025);
    petalLayer(10, 13, 45, 156, 27, 'url(#petalInner)', 0.62, 0.025);

    const centerG = el('g', {class:'center-g'});
    centerG.appendChild(el('circle', {cx:200, cy:200, r:24, fill:'url(#flowerCenter)'}));
    for(let i=0;i<10;i++){
      const a = (360/10)*i * Math.PI/180;
      const dx = 200 + Math.cos(a)*13;
      const dy = 200 + Math.sin(a)*13;
      centerG.appendChild(el('circle', {cx:dx, cy:dy, r:3, fill:'#c9832f'}));
    }
    root.appendChild(centerG);
  }

  /* ---------- wrapped bouquet: stems, leaves, varied flowers, paper wrap, ribbon ---------- */
  function createRose(cx, cy, scale){
    const g = el('g', {transform:`translate(${cx},${cy}) scale(${scale})`});
    g.appendChild(el('circle', {cx:0, cy:0, r:9, fill:'#c23b63'}));
    for(let i=0;i<6;i++){
      const a = i*60;
      const p = el('ellipse', {cx:0, cy:-11, rx:7, ry:12, fill:'#e0567f', opacity:'0.92', transform:`rotate(${a})`});
      g.appendChild(p);
    }
    return g;
  }
  function createTulip(cx, cy, scale){
    const g = el('g', {transform:`translate(${cx},${cy}) scale(${scale})`});
    const cup = el('path', {
      d:'M -14,4 C -15,-24 -8,-40 0,-42 C 8,-40 15,-24 14,4 C 8,-6 -8,-6 -14,4 Z',
      fill:'#ef7fa0'
    });
    g.appendChild(cup);
    g.appendChild(el('path', {d:'M 0,-40 C 3,-26 3,-10 0,2', stroke:'#d85c85', 'stroke-width':1.4, fill:'none', opacity:'0.7'}));
    return g;
  }
  function createDaisy(cx, cy, scale){
    const g = el('g', {transform:`translate(${cx},${cy}) scale(${scale})`});
    for(let i=0;i<9;i++){
      const a = (360/9)*i;
      g.appendChild(el('ellipse', {cx:0, cy:-13, rx:4.5, ry:12, fill:'#f7f2ff', stroke:'#e9defa', 'stroke-width':0.5, transform:`rotate(${a})`}));
    }
    g.appendChild(el('circle', {cx:0, cy:0, r:7, fill:'#f0c96b'}));
    return g;
  }
  function createPeony(cx, cy, scale){
    const g = el('g', {transform:`translate(${cx},${cy}) scale(${scale})`});
    const rings = [[18,10],[13,7],[8,4]];
    const colors = ['#f4b8d0','#ee94b8','#e0699e'];
    rings.forEach((r, ri)=>{
      const count = 8 - ri*2;
      for(let i=0;i<count;i++){
        const a = (360/count)*i + ri*14;
        const g2 = el('g', {transform:`rotate(${a})`});
        g2.appendChild(el('ellipse', {cx:0, cy:-r[0], rx:r[1], ry:r[0], fill:colors[ri], opacity:'0.9'}));
        g.appendChild(g2);
      }
    });
    g.appendChild(el('circle', {cx:0, cy:0, r:5, fill:'#fff3d9'}));
    return g;
  }
  function createLavenderSprig(cx, cy, scale){
    const g = el('g', {transform:`translate(${cx},${cy}) scale(${scale})`});
    for(let i=0;i<9;i++){
      const yy = -i*7;
      const xx = (i%2===0)? -3.5 : 3.5;
      g.appendChild(el('circle', {cx:xx, cy:yy, r:3.6, fill:'#8a6bc4'}));
    }
    return g;
  }
  function createBabiesBreath(cx, cy, scale){
    const g = el('g', {transform:`translate(${cx},${cy}) scale(${scale})`});
    for(let i=0;i<7;i++){
      const a = Math.random()*Math.PI*2;
      const r = 6 + Math.random()*10;
      g.appendChild(el('circle', {cx:Math.cos(a)*r, cy:Math.sin(a)*r - 6, r:2.4, fill:'#fbf7ff', stroke:'#e9defa', 'stroke-width':0.4}));
    }
    return g;
  }

  function buildBouquet(){
    const svg = document.getElementById('bouquetSvg');
    svg.innerHTML = '';
    const defs = el('defs', {});
    defs.innerHTML = `
      <linearGradient id="wrapGrad" x1="0" y1="0" x2="0" y2="1">
        <stop offset="0%" stop-color="#f5eefe"/>
        <stop offset="100%" stop-color="#d9c6f2"/>
      </linearGradient>
      <linearGradient id="ribbonGrad" x1="0" y1="0" x2="1" y2="1">
        <stop offset="0%" stop-color="#f0a3c2"/>
        <stop offset="100%" stop-color="#9b7ebd"/>
      </linearGradient>
    `;
    svg.appendChild(defs);

    const baseX = 160, baseY = 412;

    const stems = [
      {x:160, top:96,  color:'#5c8a52', type:'peony',    scale:1.15, dly:0.42},
      {x:104, top:150, color:'#5c8a52', type:'rose',     scale:1.0,  dly:0.55},
      {x:222, top:150, color:'#5c8a52', type:'lavender', scale:1.15, dly:0.55},
      {x:70,  top:198, color:'#5c8a52', type:'daisy',    scale:1.0,  dly:0.68},
      {x:252, top:196, color:'#5c8a52', type:'tulip',    scale:1.05, dly:0.68},
      {x:160, top:222, color:'#79a06a', type:'babies',   scale:1.0,  dly:0.81}
    ];

    const stemsWrap = el('g', {id:'stemsWrap'});
    stems.forEach(s=>{
      const partG = el('g', {class:'part'});
      partG.style.setProperty('--dly', s.dly + 's');

      const ctrlX = baseX + (s.x - baseX) * 0.5;
      const ctrlY = baseY - (baseY - s.top) * 0.55;
      const stemPath = el('path', {
        d:`M ${baseX},${baseY} Q ${ctrlX},${ctrlY} ${s.x},${s.top}`,
        stroke:s.color, 'stroke-width':4.5, fill:'none', 'stroke-linecap':'round'
      });
      partG.appendChild(stemPath);

      // leaf partway up the stem
      const t = 0.55;
      const lx = (1-t)*(1-t)*baseX + 2*(1-t)*t*ctrlX + t*t*s.x;
      const ly = (1-t)*(1-t)*baseY + 2*(1-t)*t*ctrlY + t*t*s.top;
      const leafDir = s.x < baseX ? -1 : 1;
      const leaf = el('ellipse', {
        cx:lx + leafDir*10, cy:ly, rx:14, ry:6,
        fill:'#6fae5c', transform:`rotate(${leafDir*28} ${lx + leafDir*10} ${ly})`
      });
      partG.appendChild(leaf);

      let flowerG;
      if(s.type==='rose') flowerG = createRose(s.x, s.top, s.scale);
      else if(s.type==='tulip') flowerG = createTulip(s.x, s.top, s.scale);
      else if(s.type==='daisy') flowerG = createDaisy(s.x, s.top, s.scale);
      else if(s.type==='peony') flowerG = createPeony(s.x, s.top, s.scale);
      else if(s.type==='lavender') flowerG = createLavenderSprig(s.x, s.top, s.scale);
      else flowerG = createBabiesBreath(s.x, s.top, s.scale);
      partG.appendChild(flowerG);

      stemsWrap.appendChild(partG);
    });
    svg.appendChild(stemsWrap);

    // paper wrap covers the lower portion of the stems
    const wrapG = el('g', {class:'part'});
    wrapG.style.setProperty('--dly', '0s');
    const wrapPath = el('path', {
      d:'M 160,418 C 92,412 70,330 76,258 L 244,258 C 250,330 228,412 160,418 Z',
      fill:'url(#wrapGrad)', stroke:'rgba(255,255,255,0.5)', 'stroke-width':1.5
    });
    wrapG.appendChild(wrapPath);
    wrapG.appendChild(el('path', {d:'M 160,415 C 150,360 148,300 150,262', stroke:'rgba(255,255,255,0.55)', 'stroke-width':1.2, fill:'none'}));
    wrapG.appendChild(el('path', {d:'M 160,415 C 170,360 172,300 170,262', stroke:'rgba(255,255,255,0.4)', 'stroke-width':1.2, fill:'none'}));
    svg.appendChild(wrapG);

    // ribbon bow at the neck
    const ribbonG = el('g', {class:'part'});
    ribbonG.style.setProperty('--dly', '0.18s');
    ribbonG.appendChild(el('path', {d:'M 160,260 C 140,250 118,252 108,262 C 118,272 140,272 160,262 Z', fill:'url(#ribbonGrad)'}));
    ribbonG.appendChild(el('path', {d:'M 160,260 C 180,250 202,252 212,262 C 202,272 180,272 160,262 Z', fill:'url(#ribbonGrad)'}));
    ribbonG.appendChild(el('circle', {cx:160, cy:262, r:7, fill:'#7a5aa6'}));
    ribbonG.appendChild(el('path', {d:'M 154,266 L 148,300 L 156,294 L 160,306 L 164,294 L 172,300 L 166,266 Z', fill:'url(#ribbonGrad)', opacity:'0.9'}));
    svg.appendChild(ribbonG);
  }

  /* ---------- orchestration ---------- */
  openBtn.addEventListener('click', ()=>{
    showPhase(phaseBloom);
    buildBigFlower();
    requestAnimationFrame(()=>{
      document.getElementById('bigFlowerSvg').classList.add('bloom');
    });
    setTimeout(()=> sparkleBurst(phaseBloom, 14), 700);
    setTimeout(()=>{
      document.getElementById('flowerSpinWrap').classList.add('spin');
    }, 1500);

    setTimeout(()=>{
      showPhase(phaseBouquet);
      buildBouquet();
      requestAnimationFrame(()=>{
        document.getElementById('bouquetSvg').classList.add('bloom');
      });
    }, 3200);
  });

  continueBtn.addEventListener('click', ()=>{
    introOverlay.classList.add('hidden');
    document.body.classList.remove('locked');
  });
})();

/* ============== floating petals (background, whole site) ============== */
(function(){
  const field = document.getElementById('petalField');
  const emojis = ['💮','🌸','💜','✿'];
  const count = window.innerWidth < 560 ? 10 : 18;
  for(let i=0;i<count;i++){
    const p = document.createElement('div');
    p.className = 'petal';
    p.textContent = emojis[i % emojis.length];
    p.style.left = Math.random()*100 + 'vw';
    p.style.animationDuration = (10 + Math.random()*10) + 's';
    p.style.animationDelay = (Math.random()*10) + 's';
    p.style.fontSize = (14 + Math.random()*14) + 'px';
    field.appendChild(p);
  }
})();

